insert into public.products (id, category_id, name, slug, short_description, description, price, compare_at_price, sku, stock_quantity, status, featured, material, care_instructions, details, sales_count, created_at) values ('ee1e6ee1-d0be-59cb-a36e-81f3e48dfdb1', '99dfb92d-36fd-5580-af04-1f9f475156f8', 'Gulab', 'gulab', 'Unstitched 3 Piece in fluid chiffon, with embroidered neckline panel.', 'Gulab is cut from fluid chiffon with a gentle drape and soft lining. The dusty rose base is finished with tonal threadwork at the neckline and a scalloped border along the hem, so it reads quietly elegant by day and catches the light in the evening.
