insert into public.products (id, category_id, name, slug, short_description, description, price, compare_at_price, sku, stock_quantity, status, featured, material, care_instructions, details, sales_count, created_at) values ('885ef570-c3d0-539f-a20a-f7a953b0129b', '7e4e6ab2-0002-5900-a484-0a0c33b1e37b', 'Samar', 'samar', 'Unstitched 2 Piece in breathable, fine-count cotton lawn, with embroidered neckline panel.', 'Samar is cut from breathable, fine-count cotton lawn that softens with every wash. The pistachio base is finished with an all-over print of trailing vines and buti motifs, with a printed border along the hem, so it feels fresh and easy through long summer days.
