insert into public.pages (slug, title, summary, content) values ('privacy-policy', 'Privacy Policy', 'How we collect, use and protect your personal information when you shop with AURAQ.', 'AURAQ ("we", "us", "our") respects your privacy. This policy explains what personal information we collect when you visit our website or place an order, how we use it, and the choices you have.
insert into public.pages (slug, title, summary, content) values ('return-policy', 'Return & Exchange Policy', 'Exchanges within 14 days, store credit and how to start a return.', 'We want you to love what you ordered. If something isn''t right, we''re happy to help.
insert into public.pages (slug, title, summary, content) values ('shipping-policy', 'Shipping Policy', 'Delivery times, charges and tracking for orders within Pakistan and worldwide.', '## Processing time
insert into public.pages (slug, title, summary, content) values ('cancellation-policy', 'Cancellation Policy', 'When and how an order can be cancelled.', '## Cancelling your order
insert into public.pages (slug, title, summary, content) values ('terms-and-conditions', 'Terms & Conditions', 'The terms that apply when you use our website and place an order.', 'These terms govern your use of the AURAQ website and any purchase you make from us. By using the website or placing an order, you agree to these terms.
insert into public.pages (slug, title, summary, content) values ('faqs', 'Frequently Asked Questions', 'Answers to common questions about orders, sizing, delivery and exchanges.', '## Orders & payment
insert into public.pages (slug, title, summary, content) values ('contact', 'Contact Us', 'We''re here to help Monday to Saturday, 10am to 8pm PKT.', '## Customer care
