insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('ec7b295f-a553-533a-a92a-33a1a3f0be83', '85aa9d2e-cbad-552a-ad06-bab52e17d01b', 5, 'Even more beautiful in person', 'The embroidery on the neckline is so finely done and the organza dupatta drapes perfectly. Wore it to my sister’s mehndi and was asked about it all evening.', 'approved', now() - interval '30 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('d011d3bb-ff39-5ffe-aacc-17e3d8e4520c', 'fa98780f-c6fa-5fbc-a1b4-73dd3336ccfb', 5, 'True to size, lovely fabric', 'I was unsure about ordering formals online but the size guide was accurate. Delivered to Karachi in two days and beautifully packed.', 'approved', now() - interval '29 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('9215e5c4-5192-561a-a63f-32ef53e589ee', '67b3917d-b160-5b67-a34d-4846fa45f4f4', 5, 'Worth every rupee', 'Ordered to London for Eid. The colour is exactly as pictured, and the exchange process for a different size was effortless.', 'approved', now() - interval '28 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('9215e5c4-5192-561a-a63f-32ef53e589ee', 'e6ec8348-25de-5bec-a3bb-90f6b8064646', 4, 'Elegant and comfortable', 'Beautiful raw silk with a soft lining. The trouser runs slightly long for me but the shirt fits perfectly.', 'approved', now() - interval '27 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('9215e5c4-5192-561a-a63f-32ef53e589ee', '0123c76f-576b-502b-adda-631a3963ed97', 5, 'My favourite purchase this year', 'The lavender is so soft and the handwork is exquisite. Compliments all night at a wedding dinner.', 'approved', now() - interval '26 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('ccf5dc3f-9be9-59e6-ad10-7f446e252261', '462ec861-bc4c-52ce-a0d5-6821be42f4b1', 5, 'Perfect everyday suit', 'Breathable lawn and the print is gorgeous. Bought it on sale — great value for the quality.', 'approved', now() - interval '25 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('ccf5dc3f-9be9-59e6-ad10-7f446e252261', '85aa9d2e-cbad-552a-ad06-bab52e17d01b', 4, 'Pretty colour', 'Lovely colour and very comfortable in the heat. Colour faded very slightly after a few washes in warm water, so wash cold.', 'approved', now() - interval '24 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('eadb0433-aca6-50e2-a0b9-5142031436ed', 'fa98780f-c6fa-5fbc-a1b4-73dd3336ccfb', 5, 'Chic co-ord set', 'Modern cut and the sand colour is very versatile. I wear the trousers with other kurtas too.', 'approved', now() - interval '23 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('eadb0433-aca6-50e2-a0b9-5142031436ed', 'e6ec8348-25de-5bec-a3bb-90f6b8064646', 5, 'Great fit', 'Fits beautifully and the cotton net is lighter than I expected. Perfect for summer dinners.', 'approved', now() - interval '22 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('d011d3bb-ff39-5ffe-aacc-17e3d8e4520c', '67b3917d-b160-5b67-a34d-4846fa45f4f4', 5, 'Festive perfection', 'The gold border catches the light so beautifully. Packaging felt like a gift.', 'approved', now() - interval '21 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('d011d3bb-ff39-5ffe-aacc-17e3d8e4520c', '0123c76f-576b-502b-adda-631a3963ed97', 4, 'Lovely, slightly sheer', 'Gorgeous suit, the chiffon is a little sheer so I wore a slip underneath. Otherwise perfect.', 'approved', now() - interval '20 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('a14117db-f557-5b16-ab52-e12dc3e403d8', '462ec861-bc4c-52ce-a0d5-6821be42f4b1', 5, 'Stunning formal', 'This kalidar is breathtaking. Heavy, rich fabric and the zardozi is hand finished. Wore it for my nikkah dinner.', 'approved', now() - interval '19 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('e0ad8298-c622-5697-a42d-ebda120beac4', '85aa9d2e-cbad-552a-ad06-bab52e17d01b', 5, 'Like a dream', 'The powder blue is so soft and elegant. Fits exactly to the size chart.', 'approved', now() - interval '18 days');
insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('c1174ae2-6cdb-564c-acde-bd3e219ffc17', 'e6ec8348-25de-5bec-a3bb-90f6b8064646', 5, 'Best lawn of the season', 'Soft lawn that stitched beautifully. Sold out quickly for a reason!', 'approved', now() - interval '17 days');
